static void dcon_remove ( struct i2c_client * client ) { struct dcon_priv * dcon = i2c_get_clientdata ( client ) ; unregister_reboot_notifier ( & dcon -> reboot_nb ) ; atomic_notifier_chain_unregister ( & panic_notifier_list , & dcon_panic_nb ) ; free_irq ( DCON_IRQ , dcon ) ; backlight_device_unregister ( dcon -> bl_dev ) ; if ( dcon_device ) { platform_device_unregister ( dcon_device ) ; } cancel_work_sync ( & dcon -> switch_source ) ; } 